from itertools import permutations

def simulate_survival(G, P_tuple, K_rounds):
    """
    Simulates the elimination process for a given permutation P_tuple.
    (Reusing the function from previous calculation)
    """
    P = list(P_tuple)
    A = [True] * G

    for k in range(K_rounds):
        P_next = [0] * G

        for i in range(G):
            if A[i]:
                tag_to_pass = P[i]
                j = (i + 1) % G
                P_next[j] = tag_to_pass

        A_new = [False] * G
        P_new = [0] * G

        for i in range(G):
            if A[i]:
                if P_next[i] == i + 1:
                    pass
                else:
                    A_new[i] = True
                    P_new[i] = P_next[i]
            else:
                A_new[i] = False
                P_new[i] = 0

        A = A_new
        P = P_new

        if not any(A):
            return False

    return any(A)

def count_survivors(G, K_rounds):
    tags = list(range(1, G + 1))
    count = 0

    for p_tuple in permutations(tags):
        if simulate_survival(G, p_tuple, K_rounds):
            count += 1

    return count

# Calculate for G=5, K=4 (Required specific count)
