import itertools

def simulate_game(N, P, R):
    # [Simulation logic as defined before]
    tags_held = {}
    active_guests = set(range(N))
    for i in range(N):
        tags_held[i] = P[i]

    for r in range(R):
        survivors = set()
        tags_of_survivors = {}

        for i in active_guests:
            if tags_held[i] != (i + 1):
                survivors.add(i)
                tags_of_survivors[i] = tags_held[i]

        if not survivors:
            return 0

        active_guests = survivors

        new_tags_held = {}
        sorted_survivors = sorted(list(survivors))
        num_survivors = len(sorted_survivors)

        for i in range(num_survivors):
            current_guest_index = sorted_survivors[i]
            tag_to_pass = tags_of_survivors[current_guest_index]

            recipient_index = sorted_survivors[(i + 1) % num_survivors]

            new_tags_held[recipient_index] = tag_to_pass

        tags_held = new_tags_held

    return len(active_guests)

# --- Task 2 verification: N=5, R=4 ---
N5 = 5
R5 = 4
surviving_perms_5 = []

for p_tuple in itertools.permutations(range(1, N5 + 1)):
    P = list(p_tuple)
    survivors = simulate_game(N5, P, R5)
    if survivors > 0:
        surviving_perms_5.append(p_tuple)

print(f"N=5, R=4. Permutations resulting in AT LEAST ONE survivor: {len(surviving_perms_5)}")
